(window.__quranSurahs=window.__quranSurahs||{})[111]={"nomPhon":"Al-Masad","versets":{"1":{"text":"Que périssent les deux mains d'Abû-Lahab et que lui-même périsse.","arabe":"تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ"},"2":{"text":"Sa fortune ne lui sert à rien, ni ce qu'il a acquis.","arabe":"مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ"},"3":{"text":"Il sera brûlé dans un Feu plein de flammes,","arabe":"سَيَصْلَىٰ نَارًۭا ذَاتَ لَهَبٍۢ"},"4":{"text":"de même sa femme, la porteuse de bois,","arabe":"وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ"},"5":{"text":"à son cou, une corde de fibres.","arabe":"فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ"}}};